BEGIN;


CREATE TABLE IF NOT EXISTS facultades (
    id TEXT PRIMARY KEY,
    nombre TEXT UNIQUE NOT NULL,
    codigo TEXT UNIQUE,
    "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS carreras (
    id TEXT PRIMARY KEY,
    nombre TEXT NOT NULL,
    "facultadId" TEXT NOT NULL REFERENCES facultades(id) ON DELETE CASCADE,
    "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT carreras_facultadId_nombre_key UNIQUE ("facultadId", nombre)
);

CREATE TABLE IF NOT EXISTS instituciones_destino (
    id TEXT PRIMARY KEY,
    nombre TEXT UNIQUE NOT NULL,
    pais TEXT NOT NULL,
    "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS programas_doctorales (
    id TEXT PRIMARY KEY,
    nombre TEXT NOT NULL,
    "tituloAObtener" TEXT,
    "institucionDestinoId" TEXT NOT NULL REFERENCES instituciones_destino(id) ON DELETE CASCADE,
    "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT programas_institucion_nombre_key UNIQUE ("institucionDestinoId", nombre)
);

CREATE TABLE IF NOT EXISTS convenios (
    id TEXT PRIMARY KEY,
    nombre TEXT UNIQUE NOT NULL,
    "fechaInicio" TIMESTAMPTZ,
    "fechaFin" TIMESTAMPTZ,
    "institucionDestinoId" TEXT REFERENCES instituciones_destino(id) ON DELETE SET NULL,
    "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS doctorandos (
    id TEXT PRIMARY KEY,
    carpeta TEXT,
    "numeroOrden" INTEGER,
    cedula TEXT UNIQUE NOT NULL,
    apellidos TEXT NOT NULL,
    nombres TEXT NOT NULL,
    sexo TEXT,
    "fechaNacimiento" TIMESTAMPTZ,
    "correoInstitucional" TEXT UNIQUE NOT NULL,
    telefono TEXT,
    "tituloTercerNivel" TEXT,
    "tituloCuartoNivel" TEXT,
    "facultadId" TEXT REFERENCES facultades(id) ON DELETE SET NULL,
    "carreraId" TEXT REFERENCES carreras(id) ON DELETE SET NULL,
    "userId" TEXT UNIQUE,
    "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS expedientes_doctorales (
    id TEXT PRIMARY KEY,
    "doctorandoId" TEXT NOT NULL REFERENCES doctorandos(id) ON DELETE CASCADE,
    "programaDoctoralId" TEXT NOT NULL REFERENCES programas_doctorales(id) ON DELETE CASCADE,
    "convenioId" TEXT REFERENCES convenios(id) ON DELETE SET NULL,
    "tituloInvestigacion" TEXT,
    "oficioRegistroProyecto" TEXT,
    "fechaOficioRegistro" TIMESTAMPTZ,
    "tipoFinanciamiento" TEXT NOT NULL DEFAULT 'Beca',
    "tieneApoyoProyecto" BOOLEAN NOT NULL DEFAULT FALSE,
    "contratoInicio" TIMESTAMPTZ,
    "contratoFin" TIMESTAMPTZ,
    "contratoMeses" DOUBLE PRECISION,
    estado TEXT NOT NULL DEFAULT 'EN_ESTUDIOS',
    observaciones TEXT,
    "tieneAlertaLegal" BOOLEAN NOT NULL DEFAULT FALSE,
    "historialInformes" TEXT,
    "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS adendas_contrato (
    id TEXT PRIMARY KEY,
    "expedienteId" TEXT NOT NULL REFERENCES expedientes_doctorales(id) ON DELETE CASCADE,
    "numeroAdenda" INTEGER NOT NULL,
    "fechaInicio" TIMESTAMPTZ,
    "fechaFin" TIMESTAMPTZ,
    meses DOUBLE PRECISION,
    "tipoModificacion" TEXT,
    "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT adendas_expediente_numero_key UNIQUE ("expedienteId", "numeroAdenda")
);

CREATE TABLE IF NOT EXISTS devengamientos (
    id TEXT PRIMARY KEY,
    "expedienteId" TEXT UNIQUE NOT NULL REFERENCES expedientes_doctorales(id) ON DELETE CASCADE,
    "fechaInicio" TIMESTAMPTZ,
    "tiempoTexto" TEXT,
    "fechaFinEstimada" TIMESTAMPTZ,
    "oficioNotificacion" TEXT,
    "oficioActaTerminacion" TEXT,
    "oficioCierreProyecto" TEXT,
    "registroSenescyt" TEXT,
    estado TEXT NOT NULL DEFAULT 'PENDIENTE',
    "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

